  const p = SunCalc.getPosition(date, lat, lng)
  const az = p.azimuth * R, alt = p.altitude * R
  return [Math.sin(az) * Math.cos(alt), Math.sin(alt), -Math.cos(az) * Math.cos(alt)]
}

